/**
 * middleware/validateBookInput.js
 * Input validation middleware for POST /api/books.
 *
 * Runs before the controller and checks every field of the request body.
 * If anything is wrong it stops the request and returns 400 Bad Request
 * with a list of all the problems found, so bad data never reaches the
 * in-memory store.
 */

// Fields a client is allowed to send (id is generated by the server)
const ALLOWED_FIELDS = ['title', 'author', 'genre', 'year', 'price'];

// Helper: true when the value is a string with at least one non-space character
const isNonEmptyString = (value) => typeof value === 'string' && value.trim().length > 0;

const validateBookInput = (req, res, next) => {
  const body = req.body;
  const errors = [];

  // 1. The body must be a JSON object
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return res.status(400).json({
      error: 'Validation failed',
      details: ['Request body must be a JSON object'],
    });
  }

  // 2. Reject fields that are not part of a book (including id)
  const unknownFields = Object.keys(body).filter((key) => !ALLOWED_FIELDS.includes(key));
  if (unknownFields.length > 0) {
    errors.push(`Unknown field(s) not allowed: ${unknownFields.join(', ')}`);
  }

  // 3. title: required string, 1-100 characters
  if (!isNonEmptyString(body.title)) {
    errors.push('title is required and must be a non-empty string');
  } else if (body.title.trim().length > 100) {
    errors.push('title must be 100 characters or fewer');
  }

  // 4. author: required string, letters, spaces, full stops, hyphens and apostrophes only
  if (!isNonEmptyString(body.author)) {
    errors.push('author is required and must be a non-empty string');
  } else if (!/^[A-Za-z\s.'-]{2,60}$/.test(body.author.trim())) {
    errors.push("author must be 2-60 characters and contain only letters, spaces, . ' or -");
  }

  // 5. genre: required string, 2-30 characters
  if (!isNonEmptyString(body.genre)) {
    errors.push('genre is required and must be a non-empty string');
  } else if (body.genre.trim().length < 2 || body.genre.trim().length > 30) {
    errors.push('genre must be between 2 and 30 characters');
  }

  // 6. year: required whole number between 1450 (printing press) and the current year
  const currentYear = new Date().getFullYear();
  if (body.year === undefined || body.year === null || body.year === '') {
    errors.push('year is required');
  } else if (!Number.isInteger(body.year) || body.year < 1450 || body.year > currentYear) {
    errors.push(`year must be a whole number between 1450 and ${currentYear}`);
  }

  // 7. price: required positive number
  if (body.price === undefined || body.price === null || body.price === '') {
    errors.push('price is required');
  } else if (typeof body.price !== 'number' || !Number.isFinite(body.price) || body.price <= 0) {
    errors.push('price must be a number greater than 0');
  }

  // Any errors: stop here and tell the client what to fix
  if (errors.length > 0) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors,
    });
  }

  // All checks passed: continue to the controller
  return next();
};

module.exports = validateBookInput;
